const $=id=>document.getElementById(id);let analyzed=false;
function wave(t,base){let d='';for(let i=0;i<=690;i+=3){const time=i/690*1.5,z=(time-t)/.018,y=base-28*Math.exp(-z*z/2)*Math.cos(z*2);d+=(i?'L':'M')+(35+i)+','+y.toFixed(2)}return d}
function update(){const x=Number($('position').value),c=Number($('speed').value),normal=$('mode').value==='normal',px=50+x/1000*660;$('positionValue').textContent=x+' م';$('position').disabled=normal;$('leakDot').style.display=normal?'none':'';['dot','halo'].forEach(id=>$(id).setAttribute('cx',px));$('dotLabel').setAttribute('x',px);const a=x/c,b=(1000-x)/c;$('waveA').setAttribute('d',wave(analyzed&&!normal?a:-2,65));$('waveB').setAttribute('d',wave(analyzed&&!normal?b:-2,112));if(!analyzed){$('status').textContent='جاهز للتحليل';['resultX','resultDt','resultT'].forEach(id=>$(id).textContent='—');$('explanation').textContent='غيّر موقع الحدث ثم شغّل التحليل لمقارنة توقيت وصول الإشارة.';return}if(normal){$('status').textContent='لم يُحاكَ أي حدث';['resultX','resultDt','resultT'].forEach(id=>$(id).textContent='—');$('explanation').textContent='لا توجد إشارة حدث في هذا السيناريو. هذا لا يثبت خلو شبكة حقيقية من التسرب.';return}const estimate=(1000-c*(b-a))/2;$('status').textContent='اكتمل التحليل الافتراضي';$('resultX').textContent=estimate.toFixed(0)+' م';$('resultDt').textContent=((b-a)*1000).toFixed(0)+' ms';$('resultT').textContent=a.toFixed(3)+' / '+b.toFixed(3)+' s';$('explanation').textContent='الموقع المحسوب: '+estimate.toFixed(0)+' متر من A. تطابقه مع المدخلات ناتج عن النموذج المثالي، ولا يعبّر عن دقة مثبتة ميدانيًا.'}
['position','speed','mode'].forEach(id=>$(id).addEventListener('input',()=>{analyzed=false;update()}));$('run').addEventListener('click',()=>{analyzed=true;update()});$('reset').addEventListener('click',()=>{$('position').value='360';$('speed').value='1000';$('mode').value='leak';analyzed=false;update()});update();
